.darma-loader-darma-b9-bar-chart-grow { --accent: var(--loader-color, #10b981); --accent-2: var(--loader-secondary-color, #34d399); width: var(--loader-size, 80px); height: calc(var(--loader-size, 80px) * .72); display: flex; align-items: flex-end; gap: calc(var(--loader-size, 80px) * .05); }
.darma-loader-darma-b9-bar-chart-grow span { flex: 1; background: linear-gradient(var(--accent-2), var(--accent)); border-radius: calc(var(--loader-size, 80px) * .02) calc(var(--loader-size, 80px) * .02) 0 0; }
.darma-loader-darma-b9-bar-chart-grow span:nth-child(1) { animation: darma-loader-darma-b9-bar-chart-grow-grow-a calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-darma-b9-bar-chart-grow span:nth-child(2) { animation: darma-loader-darma-b9-bar-chart-grow-grow-b calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-darma-b9-bar-chart-grow span:nth-child(3) { animation: darma-loader-darma-b9-bar-chart-grow-grow-c calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-darma-b9-bar-chart-grow span:nth-child(4) { animation: darma-loader-darma-b9-bar-chart-grow-grow-d calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-darma-b9-bar-chart-grow span:nth-child(5) { animation: darma-loader-darma-b9-bar-chart-grow-grow-e calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
@keyframes darma-loader-darma-b9-bar-chart-grow-grow-a { 0%, 100% { height: 30%; } 50% { height: 72%; } }
@keyframes darma-loader-darma-b9-bar-chart-grow-grow-b { 0%, 100% { height: 62%; } 50% { height: 96%; } }
@keyframes darma-loader-darma-b9-bar-chart-grow-grow-c { 0%, 100% { height: 44%; } 50% { height: 60%; } }
@keyframes darma-loader-darma-b9-bar-chart-grow-grow-d { 0%, 100% { height: 80%; } 50% { height: 38%; } }
@keyframes darma-loader-darma-b9-bar-chart-grow-grow-e { 0%, 100% { height: 52%; } 50% { height: 88%; } }

